import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int A = Integer.parseInt(st.nextToken());
        int B = Integer.parseInt(st.nextToken());

        int[] seqA = new int[A];
        int idx = 0;

        while (idx < A) {
            if (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            while (st.hasMoreTokens() && idx < A) {
                seqA[idx++] = Integer.parseInt(st.nextToken());
            }
        }

        int j = 0;
        boolean ok = true;

        for (int i = 0; i < B; i++) {
            while (j < A && seqA[j] != getNextInt(br, st)) {
                j++;
            }
            if (j == A) {
                ok = false;
                break;
            }
            j++;
        }

        System.out.println(ok ? "S" : "N");
    }

    private static int nextInt(BufferedReader br, StringTokenizer st) throws IOException {
        return 0;
    }
}
